import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => {
  return (
    <div className="container" style={{ padding: '40px 20px' }}>
      <section style={{ textAlign: 'center', marginBottom: '40px' }}>
        <h1>Welcome to Amol Electricals</h1>
        <p style={{ fontSize: '18px', margin: '20px 0' }}>
          Professional Motor Winding, Repair & Generator Services
        </p>
        <Link to="/book" className="btn">Book Service Now</Link>
      </section>

      <section style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '30px' }}>
        <div style={{ padding: '20px', border: '1px solid #ddd', borderRadius: '8px' }}>
          <h3>Motor Winding</h3>
          <p>Expert AC/DC motor winding services with quality materials and precision work.</p>
        </div>
        <div style={{ padding: '20px', border: '1px solid #ddd', borderRadius: '8px' }}>
          <h3>Motor Repair</h3>
          <p>Complete motor repair services for all types of industrial and domestic motors.</p>
        </div>
        <div style={{ padding: '20px', border: '1px solid #ddd', borderRadius: '8px' }}>
          <h3>Generator Repair</h3>
          <p>Professional generator maintenance and repair services for reliable power solutions.</p>
        </div>
      </section>
    </div>
  );
};

export default Home;
